<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor\TemplateChannelAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateChannelAccessor trait.
 *
 * Covers null default, string/VO assignment via withChannel,
 * getChannel/channel accessors, and isChannelChanged with/without original.
 */
class TemplateChannelAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withChannel creates a new instance with the Channel set
     * from a string value, and getChannel returns the primitive string.
     */
    public function testWithChannelFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateChannelAccessorUnitTest();

        // Act
        $result = $holder->withChannel(TemplateChannelOptions::MAIL);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TemplateChannelOptions::MAIL, $result->getChannel());
    }
    /**
     * Asserts that withchannel has access to the value object
     * from a string value, and getChannel returns the primitive string.
     */
    public function testWithChannelFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateChannelAccessorUnitTest();

        // Act
        $result = $holder->withChannel(TemplateChannelOptions::MAIL);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TemplateChannelOptions::MAIL, $result->channel()->value());
    }
    public function testChangedChannel(): void
    {
        // Arrange
        $holder = new ImplWithTemplateChannelAccessorUnitTest()->withChannel(TemplateChannelOptions::MAIL);
        $original = $holder->withChannel(TemplateChannelOptions::MAIL);
        $same = $holder->withChannel(TemplateChannelOptions::MAIL);
        $modified = $holder->withChannel(TemplateChannelOptions::SMS);

        // Act
        $withSame = $original->isChannelChanged($same);
        $withDiferent = $original->isChannelChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateChannelAccessorUnitTest
{
    use TemplateChannelAccessor;
}
